VALUES ('guo-r2', '郭叔', ARRAY['虢叔'], '姬', '虢', NULL, NULL, NULL, NULL, ARRAY['君主'], '郭叔（一作虢叔），西虢君主世系中的第二位，具体世系和年代失载；时间轴依相邻锚点插值。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郭叔"}]'::jsonb, NULL, NULL, '郭叔')
