VALUES ('guo-r3', '虢城公', ARRAY['虢成公'], '姬', '虢', NULL, NULL, NULL, NULL, ARRAY['君主'], '虢城公，班簋铭文所见西周虢国人物，名遣为一说；其是否西虢君主及具体年代均有争议。此处按君主列表世次收录，年代在相邻锚点间插值。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢城公"}]'::jsonb, NULL, NULL, '虢城公')
