VALUES ('guo-r6', '季', ARRAY['虢季'], '姬', '虢', NULL, NULL, NULL, NULL, ARRAY['君主'], '虢文公，周宣王时期任卿士，曾谏宣王举行籍田礼，事见《国语·周语上》。具体在位年代不详，时间轴按相邻锚点插值。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢文公"}]'::jsonb, NULL, NULL, '虢文公')
