VALUES ('guo-r7', '鼓', ARRAY['虢石甫','虢公鼓','虢硕父'], '姬', '虢', NULL, NULL, NULL, NULL, ARRAY['君主'], '虢石父，又称虢公鼓，主要活动于周幽王时期，前775年灭焦为一说。西周灭亡后其世系及去向不详；在位区间按周幽王纪年插值。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢石父"}]'::jsonb, NULL, NULL, '虢石父')
