VALUES ('guo-r8', '翰', ARRAY[]::text[], '姬', '虢', NULL, NULL, NULL, NULL, ARRAY['君主'], '虢公翰，西周末至东周初的虢国君主，一说为虢石父之子。具体在位年代及世系关系不详，时间轴依后续春秋纪事插值。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢公翰"}]'::jsonb, NULL, NULL, '虢公翰')
