VALUES ('guo-gong-chou', '丑', ARRAY['虢公醜','虢叔'], '姬', '虢', NULL, NULL, NULL, NULL, ARRAY['君主'], '虢公丑（又作虢公醜），春秋时期虢国末代君主。前673年曾与郑厉公协助周惠王平定王子颓之乱；前655年晋献公再次借道于虞伐虢，虢亡后奔周王室。继位年份不详，年代按前任出奔与后续纪事定位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢公丑"}]'::jsonb, NULL, NULL, '虢公丑')
