-- dynasties
VALUES ('guo-chunqiu', '虢', ARRAY['虢国','南虢','西虢'], 'cn', 'east_asia', -1046, 1, -655, 12, -12540, -7837, 'year', 'ochre', NULL, NULL, '周朝姬姓诸侯国。东、西虢封国及世系归属存在异说；传统始封年代依周初纪年记于前1046年。西虢东迁后据有三门峡一带，南虢以都城上阳为中心；前655年晋献公借道虞国灭虢。君主卡片据《西虢国》君主列表收录，失考区段依世次插值。')
