INSERT INTO reigns (id, dynasty_id, person_id, title, era_names, start_year, start_month, start_day, end_year, end_month, end_day, start_abs, end_abs, precision, start_date_confidence, end_date_confidence, is_main)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-zhu-zhou-wei-nue', '助纣为虐', 'idiom', 'point', 'year', FALSE, '牧野克商前后', -1046, 12, -12529, NULL, NULL, NULL, NULL, NULL, NULL, '比干谏纣王被杀，后世以「助纣为虐」喻帮凶为恶。', '比喻帮助坏人干坏事。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-jiu-chi-rou-lin', '酒池肉林', 'idiom', 'point', 'year', FALSE, '商纣王末年，前1046年前后；主要见于后世文献，史源有争议', -1046, 12, -12529, NULL, NULL, NULL, NULL, NULL, NULL, '《史记·殷本纪》载纣王以酒为池、悬肉为林，后世以此形容奢靡纵欲。', '形容生活极端奢侈、纵欲无度。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-ai-wu-ji-wu', '爱屋及乌', 'idiom', 'point', 'year', FALSE, '武王克商前后，前1046年；典出《尚书大传·牧誓》', -1046, 12, -12529, NULL, NULL, NULL, NULL, NULL, NULL, '《尚书大传·牧誓》载太公说爱人者兼其屋上之乌，后凝结为成语。', '比喻爱一个人而连带喜爱与他有关的人或物。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-zhou-gong-tu-bu', '周公吐哺', 'idiom', 'point', 'year', FALSE, '周公摄政初期，约前1041年；典出《史记·鲁周公世家》', -1041, 12, -12469, NULL, NULL, NULL, NULL, NULL, NULL, '《史记·鲁周公世家》载周公一沐三握发、一饭三吐哺，起以待士。', '形容求贤若渴、礼贤下士。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-dao-lu-yi-mu', '道路以目', 'idiom', 'point', 'year', FALSE, '国人暴动前', -841, 12, -10069, NULL, NULL, NULL, NULL, NULL, NULL, '周厉王专利暴虐，国人不敢言，道路相遇仅以目示意。', '形容严酷统治下，人们不敢交谈，路上相遇只以目示意。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-yin-jian-bu-yuan', '殷鉴不远', 'idiom', 'point', 'year', FALSE, '周厉王时期，约前841年；《大雅·荡》作年有争议', -841, 12, -10069, NULL, NULL, NULL, NULL, NULL, NULL, '《诗经·大雅·荡》以夏亡告诫殷、以殷亡告诫周，后成为鉴戒前事的成语。', '指前人的教训就在眼前，应当引以为戒。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-zhai-tai-gao-zhu', '债台高筑', 'idiom', 'point', 'year', FALSE, '周赧王五十九年，前256年；东周亡于秦前后', -256, 12, -3049, NULL, NULL, NULL, NULL, NULL, NULL, '周赧王为合纵攻秦向富户借贷，兵散后无力偿还，躲入高台，后称避债台。', '形容欠债很多，难以偿还。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-yi-gu-zuo-qi', '一鼓作气', 'idiom', 'point', 'year', FALSE, '鲁庄公十年，前684年', -684, 12, -8185, NULL, NULL, NULL, NULL, NULL, NULL, '曹刿论战：「一鼓作气，再而衰，三而竭。」齐鲁长勺之战齐师败绩。', '比喻趁劲头大的时候一下子把事情做完。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-lao-ma-shi-tu', '老马识途', 'idiom', 'point', 'year', FALSE, '齐桓公征孤竹，约前664年', -664, 12, -7945, NULL, NULL, NULL, NULL, NULL, NULL, '齐桓公征孤竹迷途，管仲曰老马识途，遣老马先导得归。', '比喻富有经验的人对情况熟悉，能起引导作用。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-chun-wang-chi-han', '唇亡齿寒', 'idiom', 'point', 'year', FALSE, '晋献公借道伐虢，前655年', -655, 12, -7837, NULL, NULL, NULL, NULL, NULL, NULL, '宫之奇谏虞公：「唇亡齿寒，虞、虢之表也。」晋借道伐虢后灭虞。', '比喻利害密切相关，一方受损另一方也难保全。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-jia-dao-fa-guo', '假道伐虢', 'idiom', 'point', 'year', FALSE, '晋灭虢，前655年；《左传》记鲁僖公五年。', -655, 12, -7837, NULL, NULL, NULL, NULL, NULL, NULL, '晋献公先以讨伐虢国为名向虞国借道，灭虢后回师袭灭虞国。《左传·僖公二年、五年》记载了这两次借道与宫之奇的劝谏。', '以借路为名，行灭亡对方之实；后用来比喻利用对方作为进攻第三方的通道，达到目的后再消灭对方。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-tui-bi-san-she', '退避三舍', 'idiom', 'point', 'year', FALSE, '城濮之战前', -632, 12, -7561, NULL, NULL, NULL, NULL, NULL, NULL, '晋文公对楚军「退避三舍」，城濮之战后晋称霸。', '比喻主动退让，避免冲突；也指退让回避。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-wen-ding-zhong-yuan', '问鼎中原', 'idiom', 'point', 'year', FALSE, '楚庄王问鼎，前605年', -605, 12, -7237, NULL, NULL, NULL, NULL, NULL, NULL, '楚庄王问鼎之大小轻重，王孙满答「在德不在鼎」，示争霸野心。', '比喻企图夺取天下或最高权力。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-bian-chang-mo-ji', '鞭长莫及', 'idiom', 'point', 'year', FALSE, '楚庄王伐郑、晋欲救，前597年', -597, 12, -7141, NULL, NULL, NULL, NULL, NULL, NULL, '《左传》楚伐郑，晋欲救，子重曰：「虽我之速，不能及马腹。」喻力所不及。', '比喻力量达不到，无法控制或影响远处的事物。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-tong-zhou-gong-ji', '同舟共济', 'idiom', 'point', 'year', FALSE, '《国语》寓言，春秋', -600, 12, -7177, NULL, NULL, NULL, NULL, NULL, NULL, '《国语》载：济人遇风，同舟遇海，相救如左右手。', '比喻在困难时同心协力，共渡难关。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-fen-dao-yang-biao', '分道扬镳', 'idiom', 'point', 'year', FALSE, '北魏孝文帝迁都洛阳后，约493年；典出《北史》', 493, 12, 5927, NULL, NULL, NULL, NULL, NULL, NULL, '北魏孝文帝迁都洛阳后，洛阳令元志与御史中尉李彪争道，孝文帝命二人分路而行。', '比喻目标不同，各走各的路；也指分道而行。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-duo-xing-bu-yi-bi-zi-bi', '多行不义必自毙', 'idiom', 'point', 'year', FALSE, '郑庄公克段，前701年', -701, 12, -8389, NULL, NULL, NULL, NULL, NULL, NULL, '《左传》郑伯克段于鄢，公曰：「多行不义必自毙，子姑待之。」', '坏事干得多了，必定会自取灭亡。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-ye-gong-hao-long', '叶公好龙', 'idiom', 'point', 'year', FALSE, '楚叶公沈诸梁，春秋中叶', -500, 12, -5977, NULL, NULL, NULL, NULL, NULL, NULL, '叶公沈诸梁好龙，室中尽雕龙文；真龙下之，叶公弃而走，失其魂魄。', '比喻表面上爱好某事物，实际上并非真正喜欢，甚至害怕。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-er-tao-sha-san-shi', '二桃杀三士', 'idiom', 'point', 'year', FALSE, '齐景公时，约前522年', -522, 12, -6241, NULL, NULL, NULL, NULL, NULL, NULL, '晏婴献二桃，公孙接、田开疆、古冶子争功，后二人自杀，古冶子亦自刎。', '比喻用阴谋借刀杀人，或借小事除掉强者。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-wo-xin-chang-dan', '卧薪尝胆', 'idiom', 'point', 'year', FALSE, '越灭吴，前473年', -473, 12, -5653, NULL, NULL, NULL, NULL, NULL, NULL, '勾践战败后屈身事吴，回国卧薪尝胆，最终灭吴称霸。', '形容刻苦自励，发愤图强。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-wei-wei-jiu-zhao', '围魏救赵', 'idiom', 'point', 'year', FALSE, '桂陵之战，前354年', -354, 12, -4225, NULL, NULL, NULL, NULL, NULL, NULL, '孙膑围魏救赵，于桂陵大败魏军。', '比喻袭击敌人后方，迫其撤兵回援。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-yi-ming-jing-ren', '一鸣惊人', 'idiom', 'point', 'year', FALSE, '齐威王在位早期，约前354年；纪年诸说不一', -354, 12, -4225, NULL, NULL, NULL, NULL, NULL, NULL, '齐威王三年不飞不鸣，淳于髡问之，王曰「一鸣而天下惊」。', '比喻平时没有突出表现，一旦有所作为就使人震惊。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-hui-ji-ji-yi', '讳疾忌医', 'idiom', 'point', 'year', FALSE, '《韩非子》载扁鹊见蔡桓侯，战国寓言', -400, 12, -4777, NULL, NULL, NULL, NULL, NULL, NULL, '蔡桓侯讳疾忌医，扁鹊每见病深一层，终不可救。', '比喻隐瞒缺点，拒绝批评和帮助。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-meng-mu-san-qian', '孟母三迁', 'idiom', 'point', 'year', FALSE, '孟子少年期于邹国，约前375年', -375, 12, -4477, NULL, NULL, NULL, NULL, NULL, NULL, '孟子幼时，孟母三迁其居，近墓则嬉墓，近市则嬉贾，近学宫则习礼。', '比喻为子女成长选择良好环境。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-lan-yu-chong-shu', '滥竽充数', 'idiom', 'point', 'year', FALSE, '齐宣王时，约前319—前301年', -310, 12, -3697, NULL, NULL, NULL, NULL, NULL, NULL, '齐宣王使三百人吹竽，南郭处士充数；湣王好一一听之，处士逃。', '比喻没有真才实学的人混在行家里面充数，或以次充好。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-san-ren-cheng-hu', '三人成虎', 'idiom', 'point', 'year', FALSE, '庞葱与太子赴邯郸，前343年', -343, 12, -4093, NULL, NULL, NULL, NULL, NULL, NULL, '庞葱将赴邯郸，恐谗言，以「三人成虎」谏魏王，王终不信。', '比喻谣言或讹传一再重复，就容易使人信以为真。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-dong-shi-xiao-pin', '东施效颦', 'idiom', 'point', 'year', FALSE, '庄子寓言', -320, 12, -3817, NULL, NULL, NULL, NULL, NULL, NULL, '《庄子》东施效西施之颦，邻人闭户不出，见其丑态。', '比喻盲目模仿别人，不但学不像，反而出丑。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-xiang-ru-yi-mo', '相濡以沫', 'idiom', 'point', 'year', FALSE, '庄子寓言', -320, 12, -3817, NULL, NULL, NULL, NULL, NULL, NULL, '《庄子》泉涸，鱼相与处于陆，相呴以湿，相濡以沫。', '比喻同处困境，相互救助；也形容夫妻感情深厚。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-dui-niu-tan-qin', '对牛弹琴', 'idiom', 'point', 'year', FALSE, '庄子寓言，一说出自牟子', -320, 12, -3817, NULL, NULL, NULL, NULL, NULL, NULL, '《庄子》公明仪为牛弹清角之操，牛食如故，非牛不闻，不合其耳。', '比喻对不能理解的人讲道理，白费口舌。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-jing-di-zhi-wa', '井底之蛙', 'idiom', 'point', 'year', FALSE, '庄子寓言', -320, 12, -3817, NULL, NULL, NULL, NULL, NULL, NULL, '《庄子》井蛙不可以语于海者，拘于虚也。', '比喻见识狭窄、眼光短浅的人。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-zhao-san-mu-si', '朝三暮四', 'idiom', 'point', 'year', FALSE, '《列子·黄帝》寓言，故事称宋有狙公；年代未详', -320, 12, -3817, NULL, NULL, NULL, NULL, NULL, NULL, '《列子·黄帝》载宋有狙公，约定朝三暮四分给群狙，群狙先怒后喜。', '原指实质未变而表面花样翻新；后多比喻反复无常。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-nan-yuan-bei-zhe', '南辕北辙', 'idiom', 'point', 'year', FALSE, '战国策寓言', -310, 12, -3697, NULL, NULL, NULL, NULL, NULL, NULL, '《战国策》有人欲之楚而北行，马良、用多、御善，愈善而离楚愈远。', '比喻行动和目的相反，越努力离目标越远。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-qi-ren-you-tian', '杞人忧天', 'idiom', 'point', 'decade', FALSE, '《列子·天瑞》未记具体年代；按杞国仍存续的春秋末期约前500年推定定位', -500, 12, -5977, NULL, NULL, NULL, NULL, NULL, NULL, '《列子》杞国有人忧天地崩坠，身无所寄，废寝食者。', '比喻不必要的或缺乏根据的忧虑和担心。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-ke-zhou-qiu-jian', '刻舟求剑', 'idiom', 'point', 'year', FALSE, '列子寓言', -300, 12, -3577, NULL, NULL, NULL, NULL, NULL, NULL, '《列子》楚人渡江剑坠，遽刻其舟曰「是吾剑所从坠」，舟止入水求之。', '比喻拘泥成例、不知变通，或办事方法不对。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-shi-fu-yi-lin', '失斧疑邻', 'idiom', 'point', 'year', FALSE, '列子寓言', -300, 12, -3577, NULL, NULL, NULL, NULL, NULL, NULL, '《列子》人有亡斧，意其邻之子；视其行步，窃斧也；既得其斧，视邻之子，不复窃斧。', '比喻没有根据就胡乱猜疑他人。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-wu-shi-bu-xiao-bai-bu', '五十步笑百步', 'idiom', 'point', 'year', FALSE, '孟子答梁惠王，约前330年', -330, 12, -3937, NULL, NULL, NULL, NULL, NULL, NULL, '《孟子》梁惠王问何以利吾国，孟子以五十步笑百步喻其好战本质未改。', '比喻自己虽有缺点，却去嘲笑别人，本质相同。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-jiao-tu-san-ku', '狡兔三窟', 'idiom', 'point', 'year', FALSE, '冯谖谏孟尝君，战国', -300, 12, -3577, NULL, NULL, NULL, NULL, NULL, NULL, '《战国策》冯谖谓孟尝君：狡兔有三窟，仅得免其死耳。', '比喻隐蔽的地方多，便于藏身或留有退路。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-wang-yang-bu-lao', '亡羊补牢', 'idiom', 'point', 'year', FALSE, '楚顷襄王逃至城阳后，约前278年', -278, 12, -3313, NULL, NULL, NULL, NULL, NULL, NULL, '《战国策》庄辛谏楚襄王：见兔而顾犬，未为晚也；亡羊而补牢，未为迟也。', '比喻出了问题后及时补救，仍可防止继续受损失。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-handan-xue-bu', '邯郸学步', 'idiom', 'point', 'year', FALSE, '庄子寓言', -300, 12, -3577, NULL, NULL, NULL, NULL, NULL, NULL, '《庄子》燕国少年学赵都邯郸之步，未能得能，又失其故步，匍匐而归。', '比喻模仿别人不成，反而失去自己原有的技能。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-ya-miao-zhu-zhang', '揠苗助长', 'idiom', 'point', 'year', FALSE, '孟子寓言', -300, 12, -3577, NULL, NULL, NULL, NULL, NULL, NULL, '《孟子》宋人揠苗助长，苗既槁矣；喻违背规律之害。', '比喻违反规律、急于求成，反而把事情弄糟。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-zheng-ren-mai-lu', '郑人买履', 'idiom', 'point', 'year', FALSE, '约前400年（寓言设定推测；原典无纪年）', -400, 12, -4777, NULL, NULL, NULL, NULL, NULL, NULL, '《韩非子》郑人买履，忘持度而返，市罢不得履，宁信度无自信也。', '比喻拘泥教条、不顾实际，或办事刻板不知变通。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-zi-xiang-mao-dun', '自相矛盾', 'idiom', 'point', 'year', FALSE, '韩非子寓言', -280, 12, -3337, NULL, NULL, NULL, NULL, NULL, NULL, '《韩非子》楚人鬻盾与矛，誉盾坚莫能陷、矛利无不陷，或曰以矛陷盾，弗能应。', '比喻言行前后抵触，不能自圆其说。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-shou-zhu-dai-tu', '守株待兔', 'idiom', 'point', 'year', FALSE, '约前300年（寓言设定推测；原典无纪年）', -300, 12, -3577, NULL, NULL, NULL, NULL, NULL, NULL, '《韩非子》宋人耕田，兔走触株折颈而死，遂守株待兔。', '比喻死守狭隘经验，不知变通，妄想不劳而获。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-mai-du-huan-zhu', '买椟还珠', 'idiom', 'point', 'year', FALSE, '韩非子寓言', -275, 12, -3277, NULL, NULL, NULL, NULL, NULL, NULL, '《韩非子》楚人卖珠于郑，椟饰以木兰、薰以桂椒，郑人买其椟而还其珠。', '比喻取舍不当，舍本逐末；也指不识货。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-hua-she-tian-zu', '画蛇添足', 'idiom', 'point', 'year', FALSE, '战国策寓言', -280, 12, -3337, NULL, NULL, NULL, NULL, NULL, NULL, '《战国策》楚人画蛇，先成者添足，酒不得饮。', '比喻做了多余的事，反而把事情弄坏。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-hu-jia-hu-wei', '狐假虎威', 'idiom', 'point', 'year', FALSE, '《战国策·楚策》楚宣王问江乙时所举寓言', -275, 12, -3277, NULL, NULL, NULL, NULL, NULL, NULL, '《战国策·楚策》载楚宣王问江乙，江乙以虎狐同行、百兽皆走为喻。', '比喻倚仗别人的势力欺压人。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-yu-bang-xiang-zheng', '鹬蚌相争', 'idiom', 'point', 'year', FALSE, '苏代谏赵惠文王，前279年', -279, 12, -3325, NULL, NULL, NULL, NULL, NULL, NULL, '《战国策》赵将伐燕，苏代以鹬蚌相争、渔翁得利谏赵王。', '比喻双方相持不下，让第三方从中得利。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-tang-lang-bu-chan', '螳螂捕蝉', 'idiom', 'point', 'year', FALSE, '吴王欲伐荆的寓言，未具名，约春秋末', -500, 12, -5977, NULL, NULL, NULL, NULL, NULL, NULL, '《韩非子》螳螂捕蝉，黄雀在后；吴王欲伐荆，门人以此谏止。', '比喻只顾眼前利益，不顾后患。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-zhi-shang-tan-bing', '纸上谈兵', 'idiom', 'point', 'year', FALSE, '长平之战，前260年', -260, 12, -3097, NULL, NULL, NULL, NULL, NULL, NULL, '赵括空谈兵法，长平之战代廉颇为主将，四十万赵军覆没。', '比喻空谈理论，不能解决实际问题。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-wan-bi-gui-zhao', '完璧归赵', 'idiom', 'point', 'year', FALSE, '赵惠文王十九年，前283年', -283, 12, -3373, NULL, NULL, NULL, NULL, NULL, NULL, '蔺相如持和氏璧入秦，以智谋完璧归赵。', '比喻把原物完好地归还本人。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-fu-jing-qing-zui', '负荆请罪', 'idiom', 'point', 'year', FALSE, '渑池之会后将相和，约前279年', -279, 12, -3325, NULL, NULL, NULL, NULL, NULL, NULL, '廉颇闻蔺相如避让之由，负荆请罪，二人结为刎颈之交。', '形容主动认错、道歉，请求责罚。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-mao-sui-zi-jian', '毛遂自荐', 'idiom', 'point', 'year', FALSE, '平原君合纵，前257年', -257, 12, -3061, NULL, NULL, NULL, NULL, NULL, NULL, '毛遂自荐随平原君赴楚，按剑而立，说服楚王合纵抗秦。', '比喻自告奋勇，自己推荐自己担任某项工作。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-qian-jin-mai-gu', '千金买骨', 'idiom', 'point', 'year', FALSE, '燕昭王求贤，前279年', -279, 12, -3325, NULL, NULL, NULL, NULL, NULL, NULL, '燕昭王问郭隗求贤，郭隗以千金买千里马骨喻厚待贤士。', '比喻重视人才、以优厚待遇招揽贤士。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-jing-gong-zhi-niao', '惊弓之鸟', 'idiom', 'point', 'year', FALSE, '战国策寓言，约前251年', -251, 12, -2989, NULL, NULL, NULL, NULL, NULL, NULL, '《战国策》更羸与魏王处京台，引弓虚发，雁坠，盖其伤弓未愈。', '比喻受过惊吓的人遇到类似情形就惶恐不安。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-zhi-lu-wei-ma', '指鹿为马', 'idiom', 'point', 'year', FALSE, '秦二世元年左右', -210, 12, -2497, NULL, NULL, NULL, NULL, NULL, NULL, '秦二世时赵高为试探群臣，献鹿称马，凡不顺其意者多遭迫害。', '比喻故意颠倒黑白，混淆是非。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-tu-qiong-bi-xian', '图穷匕见', 'idiom', 'point', 'year', FALSE, '秦王政二十年', -227, 12, -2701, NULL, NULL, NULL, NULL, NULL, NULL, '荆轲刺秦王，献燕督亢地图，图卷尽头露出匕首。', '比喻事情发展到最后，真相或本意显露出来。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-po-fu-chen-zhou', '破釜沉舟', 'idiom', 'point', 'year', FALSE, '巨鹿之战前后', -207, 12, -2461, NULL, NULL, NULL, NULL, NULL, NULL, '项羽渡漳水后破釜沉舟，只带三日粮，大破秦军于巨鹿。', '比喻下定决心，不顾一切地干到底。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-cheng-ye-xiao-he', '成也萧何败也萧何', 'idiom', 'point', 'year', FALSE, NULL, -196, 12, -2329, NULL, NULL, NULL, NULL, NULL, NULL, '韩信由萧何举荐而兴，又因萧何入未央宫被害。', '比喻事情的成功或失败都出于同一个人或同一原因。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-duo-duo-yi-shan', '多多益善', 'idiom', 'point', 'year', FALSE, NULL, -202, 12, -2401, NULL, NULL, NULL, NULL, NULL, NULL, '汉高祖问韩信能带多少兵，韩信答「臣，多多益善」。', '形容越多越好。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-bei-shui-yi-zhan', '背水一战', 'idiom', 'point', 'year', FALSE, '井陉之战', -204, 12, -2425, NULL, NULL, NULL, NULL, NULL, NULL, '韩信井陉背水列阵，大破赵军。', '比喻没有退路，只能决一死战。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-san-gu-mao-lu', '三顾茅庐', 'idiom', 'point', 'year', FALSE, NULL, 207, 12, 2495, NULL, NULL, NULL, NULL, NULL, NULL, '刘备三次拜访诸葛亮于隆中，终请其出山。', '比喻诚心诚意地一再邀请或拜访。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-cao-chuan-jiejian', '草船借箭', 'idiom', 'point', 'year', FALSE, '赤壁前后', 208, 12, 2507, NULL, NULL, NULL, NULL, NULL, NULL, '诸葛亮以草船趁雾向曹营「借」得十万支箭。', '比喻用智谋向敌方取得所需之物。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-wang-mei-zhi-ke', '望梅止渴', 'idiom', 'point', 'year', FALSE, NULL, 208, 12, 2507, NULL, NULL, NULL, NULL, NULL, NULL, '曹操行军士渴，言前有梅林，军士思梅生津而解渴。', '比喻用空想安慰自己。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-le-bu-si-shu', '乐不思蜀', 'idiom', 'point', 'year', FALSE, NULL, 263, 12, 3167, NULL, NULL, NULL, NULL, NULL, NULL, '刘禅降魏后，司马昭问是否思蜀，答「此间乐，不思蜀」。', '比喻乐而忘返，或安于现状不想回去。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-sima-zhao-zhi-xin-luren-jiezhi', '司马昭之心，路人皆知', 'idiom', 'point', 'month', FALSE, '甘露五年五月（260）；《三国志·魏书·高贵乡公纪》裴松之注引《汉晋春秋》，原文作“路人所知也”', 260, 5, 3124, NULL, NULL, NULL, NULL, NULL, NULL, '甘露五年，曹髦召见王沈、王经、王业，愤言「司马昭之心，路人所知也」，后凝为成语。', '比喻人的野心或意图非常明显，众人都已看出。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-ju-gong-jin-cui', '鞠躬尽瘁', 'idiom', 'point', 'year', FALSE, '五丈原病逝前后', 234, 8, 2815, NULL, NULL, NULL, NULL, NULL, NULL, '诸葛亮《后出师表》：「鞠躬尽瘁，死而后已。」', '指恭敬谨慎，竭尽心力。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-qing-jun-ru-weng', '请君入瓮', 'idiom', 'point', 'year', FALSE, NULL, 697, 12, 8375, NULL, NULL, NULL, NULL, NULL, NULL, '来俊臣设计大瓮刑具，周兴反受其法。', '比喻用某人整治别人的办法来整治他自己。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-hua-long-dian-jing', '画龙点睛', 'idiom', 'point', 'year', FALSE, '梁陈间事，成语通行于唐', 550, 12, 6611, NULL, NULL, NULL, NULL, NULL, NULL, '张僧繇在金陵安乐寺画龙，点睛后龙破壁飞去。', '比喻说话或写作在关键处点明要旨，使内容生动传神。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-tao-li-man-tian-xia', '桃李满天下', 'idiom', 'point', 'year', FALSE, NULL, 768, 12, 9227, NULL, NULL, NULL, NULL, NULL, NULL, '唐德宗称狄仁杰「桃李满天下」，后泛指门生众多。', '比喻学生或门生很多，遍布各地。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-jing-zhong-bao-guo', '精忠报国', 'idiom', 'point', 'year', FALSE, NULL, 1140, 12, 13691, NULL, NULL, NULL, NULL, NULL, NULL, '岳飞背刺「尽忠报国」，抗金名垂青史。', '竭尽忠诚，报效国家。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-cheng-men-li-xue', '程门立雪', 'idiom', 'point', 'year', FALSE, NULL, 1080, 12, 12971, NULL, NULL, NULL, NULL, NULL, NULL, '杨时、游酢候程颐于门外，雪深没膝而不敢惊动。', '比喻尊敬师长，虔诚求学。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-kai-juan-you-yi', '开卷有益', 'idiom', 'point', 'year', FALSE, NULL, 997, 12, 11975, NULL, NULL, NULL, NULL, NULL, NULL, '宋太宗赵恒对读《太平御览》者说：「开卷有益，朕不以为劳。」', '读书就有好处。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-zhi-xing-he-yi', '知行合一', 'idiom', 'point', 'year', FALSE, NULL, 1518, 12, 18227, NULL, NULL, NULL, NULL, NULL, NULL, '王阳明心学主张知与行不可分离，后成常用成语。', '认识事物的道理与在现实中运用此道理，是密不可分的。', NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, precision, is_approximate, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('idiom-gang-zheng-bu-a', '刚正不阿', 'idiom', 'point', 'year', FALSE, '嘉靖四十五年', 1565, 12, 18791, NULL, NULL, NULL, NULL, NULL, NULL, '海瑞上《治安疏》骂嘉靖，以刚直闻名。', '刚强正直，不逢迎，无偏私。', NULL, NULL)
